"-- Ensure pg_net extension is enabled (Supabase Webhooks rely on this)\nCREATE EXTENSION IF NOT EXISTS pg_net;\n\n-- Recreate the trigger function\nCREATE OR REPLACE FUNCTION public.trigger_push_delivery()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    PERFORM net.http_post(\n        url := current_setting('app.settings.supabase_url') || '/functions/v1/push-delivery',\n        headers := jsonb_build_object(\n            'Content-Type', 'application/json',\n            'Authorization', 'Bearer ' || current_setting('app.settings.supabase_anon_key')\n        ),\n        body := jsonb_build_object(\n            'type', TG_OP,\n            'table', TG_TABLE_NAME,\n            'schema', TG_TABLE_SCHEMA,\n            'record', row_to_json(NEW)\n        )\n    );\n    RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n    -- Ignore errors to prevent blocking the transaction\n    RETURN NEW;\nEND;\n$function$\n;\n\n-- Drop old triggers if they exist\nDROP TRIGGER IF EXISTS direct_messages_push_delivery ON public.direct_messages;\nDROP TRIGGER IF EXISTS \"Push Delivery - DMs\" ON public.direct_messages;\n\nDROP TRIGGER IF EXISTS notifications_push_delivery ON public.notifications;\nDROP TRIGGER IF EXISTS \"Push Delivery - Notifications\" ON public.notifications;\n\nDROP TRIGGER IF EXISTS project_space_messages_push_delivery ON public.project_space_messages;\nDROP TRIGGER IF EXISTS \"Push Delivery - Projects\" ON public.project_space_messages;\n\nDROP TRIGGER IF EXISTS room_messages_push_delivery ON public.room_messages;\nDROP TRIGGER IF EXISTS \"Push Delivery - Rooms\" ON public.room_messages;\n\n-- Create triggers using our trigger_push_delivery function\nCREATE TRIGGER direct_messages_push_delivery\nAFTER INSERT ON public.direct_messages\nFOR EACH ROW\nEXECUTE FUNCTION public.trigger_push_delivery();\n\nCREATE TRIGGER notifications_push_delivery\nAFTER INSERT ON public.notifications\nFOR EACH ROW\nEXECUTE FUNCTION public.trigger_push_delivery();\n